"""Checkout pricing with promotion handling.

DECISION (provisional, pending product): an expired promotion is ignored,
not rejected. The order proceeds at full price and the result carries a
warning so the UI can tell the customer the promo was not applied.
Rationale: rejecting loses the sale; asking for confirmation needs UI flow
that doesn't exist yet. Change `EXPIRED_PROMO_POLICY` to revisit.
"""
from dataclasses import dataclass, field
from datetime import datetime
from decimal import Decimal

EXPIRED_PROMO_POLICY = "ignore"  # "ignore" | "reject" (confirm not implemented)


class ExpiredPromotionError(Exception):
    pass


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


@dataclass(frozen=True)
class CheckoutResult:
    subtotal: Decimal
    total: Decimal
    applied_promo: str | None = None
    warnings: list[str] = field(default_factory=list)


def checkout(subtotal: Decimal, promo: Promotion | None, now: datetime) -> CheckoutResult:
    if promo is None:
        return CheckoutResult(subtotal, subtotal)
    if now >= promo.expires_at:
        if EXPIRED_PROMO_POLICY == "reject":
            raise ExpiredPromotionError(promo.code)
        return CheckoutResult(subtotal, subtotal, None,
                              [f"Promotion {promo.code} has expired and was not applied"])
    total = (subtotal * (100 - promo.percent_off) / 100).quantize(Decimal("0.01"))
    return CheckoutResult(subtotal, total, promo.code)
