from datetime import datetime, timedelta
from decimal import Decimal
import pytest
import checkout as c

NOW = datetime(2026, 1, 1)
def promo(delta): return c.Promotion("SAVE10", Decimal(10), NOW + delta)

def test_valid_promo_applies():
    r = c.checkout(Decimal("100"), promo(timedelta(days=1)), NOW)
    assert r.total == Decimal("90.00") and r.applied_promo == "SAVE10"

def test_expired_promo_ignored_with_warning():
    r = c.checkout(Decimal("100"), promo(-timedelta(days=1)), NOW)
    assert r.total == Decimal("100") and r.applied_promo is None
    assert "expired" in r.warnings[0]

def test_promo_expiring_exactly_now_is_expired():
    assert c.checkout(Decimal("100"), promo(timedelta(0)), NOW).applied_promo is None

def test_reject_policy(monkeypatch):
    monkeypatch.setattr(c, "EXPIRED_PROMO_POLICY", "reject")
    with pytest.raises(c.ExpiredPromotionError):
        c.checkout(Decimal("100"), promo(-timedelta(days=1)), NOW)

def test_no_promo():
    assert c.checkout(Decimal("50"), None, NOW).total == Decimal("50")
